    function mountScene(host, markup, styles, dataset, install) {
  const shadow = host.attachShadow({mode:'open'});
  const style = document.createElement('style');
  const root = document.createElement('div');
  style.textContent = styles;
  root.className = 'scene-root';
  Object.assign(root.dataset,dataset);
  root.innerHTML = markup;
  shadow.append(style,root);

  const lifetime = new AbortController();
  const cleanup = [];
  const scene = {
    destroy() {
      lifetime.abort();
      for(const dispose of cleanup) dispose();
      shadow.replaceChildren();
    },
  };
  const scopedDocument = {
    documentElement:root,
    getElementById:shadow.getElementById.bind(shadow),
    querySelector:root.querySelector.bind(root),
    querySelectorAll:root.querySelectorAll.bind(root),
    createElementNS:document.createElementNS.bind(document),
  };
  const match = query => {
    const media = matchMedia(query);
    return {
      get matches() { return media.matches; },
      addEventListener(type,listener) { media.addEventListener(type,listener,{signal:lifetime.signal}); },
    };
  };
  class SceneResizeObserver extends ResizeObserver {
    constructor(callback) {
      super(callback);
      cleanup.push(() => this.disconnect());
    }
  }
  const motion = {
    timeline(options) {
      const timeline = gsap.timeline(options);
      cleanup.push(() => timeline.kill());
      return timeline;
    },
  };
  install(scene,scopedDocument,match,SceneResizeObserver,motion);
  return scene;
}

