 window.setHelpSource=(next,nextKind=kind,nextCategory=category)=>{
  const previousSource=source;
  if(categories.has(nextCategory)&&nextCategory!==category){category=nextCategory;drawVehicle();}
  if(photoScene()&&nextKind==='sn')nextKind='vin';
  source=next==='vehicle'?'vehicle':'document';kind=['vin','sn','frame','body'].includes(nextKind)?nextKind:'vin';
  if(kind==='sn')source='vehicle';
  vehicleEntering=photoScene()&&source==='vehicle'&&previousSource!=='vehicle';
  if(vehicleEntering)vehiclePose=overview();
  if(source==='vehicle')paintVehicle(vehiclePose);else publish();
  return{source,kind,category};
 };
 window.getFocusJourney=next=>{
  if(photoScene()&&next==='sn')next='vin';
  const entering=vehicleEntering;
  vehicleEntering=false;
  kind=next;if(kind==='sn')source='vehicle';publish();
  if(source==='document')return docJourney(next);
  const target=targetPose();
  if(photoScene()||kind==='sn'){
   const from={...(entering?overview():vehiclePose),zone:0,scan:0},arrival={...target,zone:0,scan:0};
   paintVehicle(from);
   const legs=[];
   if(entering)legs.push({from,to:from,duration:usePulseDots&&kind==='vin' ? .36 : .12});
   const moving=Math.abs(from.vs-target.vs)>.0001||(!photoScene()&&(Math.abs(from.vx-target.vx)>.01||Math.abs(from.vy-target.vy)>.01));
   if(moving)legs.push({from,to:arrival,duration:entering ? .84 : .64});
   if(usePulseDots&&!entering&&!moving)legs.push({from,to:arrival,duration:.28});
   const phases=window.VinGlassFocus.phaseCount(kind);
   for(let i=0;i<phases;i++){
    legs.push({
     from:{...arrival,scan:i/phases,zone:i/phases},
     to:{...target,scan:(i+1)/phases,zone:(i+1)/phases},
     duration:kind==='sn' ? .8 : 1
    });
   }
   return{legs,targetTime:times[kind]};
  }
  return{legs:[{from:{...vehiclePose},to:target,duration:1.15}],targetTime:times[kind]};
 };
